/****************************************************************************
 * Name: usbhost_uvc_deliver_frame
 *
 * Description:
 *   Hand the assembled frame to the capture callback and reset the assembly
 *   offset.  Equivalent to Linux uvc_queue_next_buffer(): the current frame
 *   is marked done and a fresh one is started.
 *
 ****************************************************************************/

static void usbhost_uvc_deliver_frame(FAR struct usbhost_uvc_s *priv)
{
  size_t copy_len = priv->frame_offset;

  if (copy_len > 0 &&
      priv->capture_cb != NULL && priv->user_buf != NULL)
    {
      if (copy_len > priv->user_buflen)
        {
          copy_len = priv->user_buflen;
        }

      memcpy(priv->user_buf, priv->frame_buf, copy_len);
      priv->capture_cb(0, copy_len, 0, priv->capture_arg);
    }

  priv->frame_offset = 0;
}

/****************************************************************************
 * Name: usbhost_uvc_process_payload
 *
 * Description:
 *   Decode one UVC payload and assemble it into the frame buffer.  The
 *   three-stage structure (start / data / end) is ported from the Allwinner
 *   R528 RTOS-HAL reference (uvc/Class/uvc_video.c), which in turn mirrors
 *   the mainline Linux UVC driver, adapted here to this driver's single
 *   assembly buffer + capture-callback model.
 *
 *   Frame delimiting: this camera toggles the FID bit mid-frame (verified
 *   over many sessions), so the Linux default of using FID toggles as frame
 *   boundaries splits real frames in half.  We therefore run in the
 *   equivalent of UVC_QUIRK_STREAM_NO_FID mode: EOF is the sole frame
 *   boundary.  FID is retained only for bookkeeping.
 *
 ****************************************************************************/

static void usbhost_uvc_process_payload(FAR struct usbhost_uvc_s *priv,
                                        FAR const uint8_t *payload,
                                        size_t len)
{
  FAR const struct uvc_payload_header_s *header;
  uint8_t header_len;
  uint8_t info;
  uint8_t fid;
  size_t  data_len;
  size_t  maxlen;
  size_t  nbytes;

  /* ---- decode_start: sanity checks (Linux uvc_video_decode_start) ----
   *  - packet must be at least 2 bytes
   *  - bHeaderLength must be >= 2 and must not exceed the packet length
   * Malformed payloads are dropped.
   */

  if (len < 2)
    {
      return;
    }

  header     = (FAR const struct uvc_payload_header_s *)payload;
  header_len = header->bHeaderLength;
  info       = header->bmHeaderInfo;

  if (header_len < 2 || header_len > len)
    {
      return;
    }

  /* Skip payloads marked with the error bit ("error frames"). */

  if (info & UVC_HEADER_ERR)
    {
      return;
    }

  fid      = info & UVC_HEADER_FID;
  data_len = len - header_len;

  UNUSED(fid);

  /* Between frames, skip leading empty payloads.  This camera emits a long
   * burst of zero-data payloads before real video starts; appending them is
   * harmless (0 bytes) but starting a frame on one is not.  Skipping them
   * guarantees a frame always begins on the first real data payload — the
   * frame-start alignment the plain EOF-only path lacked.
   */

  if (priv->frame_offset == 0 && data_len == 0)
    {
      priv->asm_lastfid = fid;
      return;
    }

  /* ---- decode_data: copy the video data into the assembly buffer ---- */

  maxlen = priv->frame_buflen - priv->frame_offset;
  nbytes = data_len < maxlen ? data_len : maxlen;

  if (nbytes > 0)
    {
      memcpy(priv->frame_buf + priv->frame_offset,
             payload + header_len, nbytes);
      priv->frame_offset += nbytes;
    }

  /* Complete the frame if the buffer overflowed (Linux: "frame complete
   * (overflow)").  Prevents data from spilling into the next frame.
   */

  if (data_len > maxlen)
    {
      usbhost_uvc_deliver_frame(priv);
      priv->asm_lastfid = fid;
      return;
    }

  /* ---- decode_end: EOF marks the end of the frame ---- */

  if (info & UVC_HEADER_EOF)
    {
      /* Size gate: EOF on this camera is sparse but reliable; still guard
       * against delivering tiny fragments (startup noise / lost frames).
       */

      size_t gate = priv->max_frame_size > 0 ?
                    priv->max_frame_size / 2 : 1024;

      if (priv->frame_offset >= gate)
        {
          usbhost_uvc_deliver_frame(priv);
        }
      else
        {
          priv->frame_offset = 0;   /* drop undersized fragment */
        }
    }
  else if (priv->max_frame_size > 0 &&
           priv->frame_offset >= priv->max_frame_size)
    {
      /* Max-size safety net in case an EOF marker is lost. */

      usbhost_uvc_deliver_frame(priv);
    }

  priv->asm_lastfid = fid;
}

