static void usbhost_uvc_deliver_frame(FAR struct usbhost_uvc_s *priv,
                                      int reason)
{
  size_t copy_len = priv->frame_offset;

  /* DIAG: report each delivered frame — size, reason (0=EOF, 1=overflow),
   * and how many leading empty payloads were skipped since the last
   * delivery.  Lets us tell a half-frame (size << frame_size) apart from a
   * full-but-misaligned frame (size ~= frame_size).  Throttled implicitly
   * by frame rate (~30/s).
   */

  syslog(LOG_ERR, "DELIVER: bytes=%u reason=%d skipped_empty=%u\n",
         (unsigned)copy_len, reason, priv->asm_skipped);
  priv->asm_skipped = 0;

  if (copy_len > 0 &&
      priv->capture_cb != NULL && priv->user_buf != NULL)
    {
      if (copy_len > priv->user_buflen)
        {
          copy_len = priv->user_buflen;
        }

      memcpy(priv->user_buf, priv->frame_buf, copy_len);
      priv->capture_cb(0, copy_len, 0, priv->capture_arg);
    }

  priv->frame_offset = 0;
}

