941		npackets = (((size) + (psize)-1) / (psize));  // DIV_ROUND_UP(size, psize);
942		if (npackets > UVC_MAX_PACKETS)
943			npackets = UVC_MAX_PACKETS;
944	
945		hal_log_info("size=%d, psize=%d, npackets=%d\n", size, psize, npackets);
946	
947		/* Retry allocations until one succeed. */
948		for (; npackets >= 1; npackets /= 2) {
949			for (i = 0; i < UVC_URBS; ++i) {
950				stream->urb_size = psize * npackets;
951	#ifdef CONFIG_OS_MELIS
952				if (stream->urb_size > UVC_MAX_PACKETS * 3) {
953					hal_log_info("must modify memory of setting\n");
954				}
955				stream->urb_buffer[i] = (char *)stream->dev->urb_mem[i];  //esMEMS_Palloc(stream->urb_size>>10, 0);
956	#elif defined(CONFIG_KERNEL_FREERTOS)
957				// stream->urb_buffer[i] = (char *)hal_malloc(stream->urb_size);
958				stream->urb_buffer[i] = (char *)hal_malloc_align(stream->urb_size, 64);
959	#endif
960				if (!stream->urb_buffer[i]) {
961					hal_log_err("hal_malloc fail\n");
962					uvc_free_urb_buffers(stream);
963					break;
964				}
965				memset(stream->urb_buffer[i], 0xAA, stream->urb_size);
