2856	 * Name: sunxi_itd_arm
2857	 *
2858	 * Description:
2859	 *   (Re)program one ring iTD to receive up to ISOC_ITD_UFRAMES payloads,
2860	 *   one per micro-frame.  Each transaction i reads into the iTD's own DMA
2861	 *   buffer at offset i*maxpacket, so the payloads land in separate slots and
2862	 *   can be handed to the UVC layer one at a time (each still begins with its
2863	 *   own 12-byte payload header at offset 0).  nlp is preserved so the
2864	 *   periodic (interrupt) schedule that follows the iTD keeps running.
2865	 *
2866	 ****************************************************************************/
2867	
2868	static void sunxi_itd_arm(int idx, FAR uint8_t *buffer, uint32_t nlp)
2869	{
2870	  struct sunxi_itd_s    *itd    = &g_itdpool[idx];
2871	  struct sunxi_epinfo_s *epinfo = g_ring.epinfo;
2872	  uintptr_t  bufphys;
2873	  uint32_t   maxpkt = g_ring.maxpacket;
2874	
2875	  /* Bytes per micro-frame: for high-bandwidth endpoints the controller may
2876	   * issue up to `mult` packets per micro-frame back-to-back, so one payload
2877	   * slot spans mult*maxpacket bytes.  For mult==1 this is just maxpacket.
2878	   */
2879	
2880	  uint32_t   per_uf = maxpkt * (epinfo->mult ? epinfo->mult : 1);
2881	  int        uf;
2882	
2883	  itd->epinfo = epinfo;
2884	  itd->buffer = buffer;
2885	  itd->buflen = ISOC_ITD_BUFSZ;
2886	  itd->result = -EBUSY;
2887	
2888	  bufphys = (uintptr_t)sunxi_physramaddr((uintptr_t)buffer);
2889	
2890	  /* Buffer Page Pointer List (bpl[0..6]) spans 7 physical 4K pages starting
2891	   * at the (page-aligned) base of this iTD's buffer.  ISOC_ITD_BUFSZ (8K)
2892	   * needs at most 3 pages, but program all 7 defensively.  The per-page base
2893	   * must be page-aligned; the per-transaction XOFFS supplies the low 12 bits.
2894	   */
2895	
2896	  {
2897	    uintptr_t pgbase = bufphys & ITD_BUFPTR_MASK;
2898	
2899	    itd->hw.bpl[0] = sunxi_swap32(
2900	      ((uint32_t)epinfo->devaddr << ITD_BUFPTR0_DEVADDR_SHIFT) |
2901	      ((uint32_t)epinfo->epno << ITD_BUFPTR0_ENDPT_SHIFT) |
2902	      (pgbase & ITD_BUFPTR_MASK));
2903	
2904	    itd->hw.bpl[1] = sunxi_swap32(
2905	      ((uint32_t)maxpkt << ITD_BUFPTR1_MAXPKT_SHIFT) |
2906	      (epinfo->dirin ? ITD_BUFPTR1_DIRIN : ITD_BUFPTR1_DIROUT) |
2907	      ((pgbase + 0x1000) & ITD_BUFPTR_MASK));
2908	
2909	    {
2910	      uint32_t multi_val = (epinfo->mult == 3) ? ITD_BUFPTR2_MULTI_3 :
2911	                           (epinfo->mult == 2) ? ITD_BUFPTR2_MULTI_2 :
2912	                                                 ITD_BUFPTR2_MULTI_1;
2913	      itd->hw.bpl[2] = sunxi_swap32(multi_val |
2914	                                    ((pgbase + 0x2000) & ITD_BUFPTR_MASK));
2915	    }
2916	
2917	    itd->hw.bpl[3] = sunxi_swap32((pgbase + 0x3000) & ITD_BUFPTR_MASK);
2918	    itd->hw.bpl[4] = sunxi_swap32((pgbase + 0x4000) & ITD_BUFPTR_MASK);
2919	    itd->hw.bpl[5] = sunxi_swap32((pgbase + 0x5000) & ITD_BUFPTR_MASK);
2920	    itd->hw.bpl[6] = sunxi_swap32((pgbase + 0x6000) & ITD_BUFPTR_MASK);
2921	  }
2922	
2923	  /* Program all 8 transactions: transaction i reads one payload (up to
2924	   * per_uf bytes) into buffer + i*per_uf.  The offset relative to the
2925	   * page-aligned base carries both the page-select (bits 12-14) and the
2926	   * X-offset (bits 0-11).  Payloads that would run past this iTD's buffer
2927	   * are left inactive (only reachable if mult>1 makes 8*per_uf exceed the
2928	   * per-iTD buffer; our uncompressed mult==1 stream never hits this).
2929	   */
2930	
2931	  for (uf = 0; uf < ISOC_ITD_UFRAMES; uf++)
2932	    {
2933	      uint32_t slot_off = (uint32_t)uf * per_uf;
2934	      uint32_t off      = (uint32_t)(bufphys & 0xfff) + slot_off;
2935	      uint32_t pg       = off >> 12;
2936	      uint32_t page_off = off & 0xfff;
2937	      uint32_t flags;
2938	
2939	      /* bpl[0..6] map 7 pages from the page-aligned base.  A transaction
2940	       * whose data would cross beyond page 6 has no buffer pointer, so leave
2941	       * it inactive.  (With alt<=6: 8*3072=24576 < 7*4096, never triggers.)
2942	       */
2943	
2944	      if (off + per_uf > 7u * 4096u)
2945	        {
2946	          itd->hw.trans[uf] = 0;  /* No page mapping; leave inactive */
2947	          continue;
2948	        }
2949	
2950	      flags = (page_off & ITD_TRAN_XOFFS_MASK) |
2951	              ((pg << ITD_TRAN_PG_SHIFT) & ITD_TRAN_PG_MASK) |
2952	              (per_uf << ITD_TRAN_LENGTH_SHIFT) |
2953	              ITD_TRAN_STATUS_ACTIVE;
2954	
2955	      /* Interrupt on the last transaction of the iTD. */
2956	
2957	      if (uf == ISOC_ITD_UFRAMES - 1)
2958	        {
2959	          flags |= ITD_TRAN_IOC;
2960	        }
2961	
2962	      itd->hw.trans[uf] = sunxi_swap32(flags);
2963	    }
2964	
2965	  /* Set the next-link pointer for the chain. */
2966	
2967	  itd->hw.nlp = nlp;
2968	
2969	  up_clean_dcache((uintptr_t)&itd->hw,
2970	                  (uintptr_t)&itd->hw + sizeof(struct ehci_itd_s));
2971	  UP_DSB();
2972	}
