3005	  for (slot = 0; slot < FRAME_LIST_SIZE; slot++)

1215	static int itd_urb_transaction(struct ehci_iso_stream *stream,
1216				       struct ehci_hcd *ehci,
1217				       struct urb *urb,
1218				       gfp_t mem_flags)
1219	{
1220		struct ehci_itd *itd;
1221		dma_addr_t itd_dma;
1222		int i;
1223		unsigned num_itds;
1224		struct ehci_iso_sched *sched;
1225		unsigned long flags;
1226	
1227		sched = iso_sched_alloc(urb->number_of_packets, mem_flags);
1228		if (unlikely(sched == NULL))
1229			return -ENOMEM;
1230	
1231		itd_sched_init(ehci, sched, stream, urb);
1232	
1233		if (urb->interval < 8)
1234			num_itds = 1 + (sched->span + 7) / 8;
1235		else
1236			num_itds = urb->number_of_packets;
1237	
1238		/* allocate/init ITDs */
1239		flags = hal_spin_lock_irqsave(&ehci->lock);
1240		for (i = 0; i < num_itds; i++) {
1241			/*
1242			 * Use iTDs from the free list, but not iTDs that may
1243			 * still be in use by the hardware.
1244			 */
1245			if (likely(!list_empty(&stream->free_list))) {
1246				itd = list_first_entry(&stream->free_list, struct ehci_itd, itd_list);
1247				if (itd->frame == ehci->now_frame)
1248					goto alloc_itd;
1249				list_del(&itd->itd_list);
1250				itd_dma = itd->itd_dma;
1251			} else {
1252	alloc_itd:
1253				hal_spin_unlock_irqrestore(&ehci->lock, flags);
1254				// itd = dma_pool_alloc(ehci->itd_pool, mem_flags,
1255				//		&itd_dma);
1256				itd = usb_dma_malloc(sizeof(struct ehci_itd), &itd_dma,
1257						     USB_DESC_MALLOC_ALIGN_SIZE);
1258				flags = hal_spin_lock_irqsave(&ehci->lock);
1259				if (!itd) {
1260					iso_sched_free(stream, sched);
1261					hal_spin_unlock_irqrestore(&ehci->lock, flags);
1262					return -ENOMEM;
1263				}
1264			}
1265	
1266			memset(itd, 0, sizeof(*itd));
1267			itd->itd_dma = itd_dma;
1268			itd->frame = NO_FRAME;
1269			list_add(&itd->itd_list, &sched->td_list);
1270		}
1271		hal_spin_unlock_irqrestore(&ehci->lock, flags);
1272	
1273		/* temporarily store schedule info in hcpriv */
1274		urb->hcpriv = sched;
1275		urb->error_count = 0;
1276		return 0;
1277	}
