3039	  if (buffer == NULL || buflen == 0)
3040	    {
3041	      return -EINVAL;
3042	    }
3043	
3044	  /* If the ring is already running, just latch the caller buffer. */
3045	
3046	  if (g_ring.epinfo == epinfo && g_ring.buf != NULL)
3047	    {
