3086	/****************************************************************************
3087	 * Name: sunxi_isoc_teardown
3088	 *
3089	 * Description:
3090	 *   Detach the ring from the periodic frame list, restoring every slot to
3091	 *   the interrupt QH link, and mark the ring inactive.  Called on endpoint
3092	 *   cancel/free.  The DMA buffer is retained for reuse.
3093	 *
3094	 ****************************************************************************/
3095	
3096	static void sunxi_isoc_teardown(void)
3097	{
3098	  if (g_ring.epinfo == NULL)
3099	    {
3100	      return;
3101	    }
3102	
3103	  /* Restore every frame-list slot to the interrupt QH link.  The iTD
3104	   * nlp pointers are stale but harmless — the controller follows the
3105	   * frame-list slot, and the QH link is what matters.
3106	   */
3107	
3108	  {
3109	    int slot;
3110	
3111	    for (slot = 0; slot < FRAME_LIST_SIZE; slot++)
3112	      {
3113	        g_framelist[slot] = g_ring.nlp;
3114	      }
3115	
3116	    up_clean_dcache((uintptr_t)&g_framelist[0],
3117	                    (uintptr_t)&g_framelist[0] +
3118	                    FRAME_LIST_SIZE * sizeof(uint32_t));
3119	    UP_DSB();
3120	  }
3121	
3122	  g_ring.epinfo   = NULL;
3123	  g_ring.user_buf = NULL;
3124	  g_ring.f_cnt    = 0;
3125	}
