static void usbhost_uvc_process_payload(FAR struct usbhost_uvc_s *priv,
                                        FAR const uint8_t *payload,
                                        size_t len)
{
  FAR const struct uvc_payload_header_s *header;
  uint8_t header_len;
  uint8_t info;
  uint8_t fid;
  size_t  data_len;
  size_t  maxlen;
  size_t  nbytes;

  /* ---- decode_start: sanity checks (Linux uvc_video_decode_start) ----
   *  - packet must be at least 2 bytes
   *  - bHeaderLength must be >= 2 and must not exceed the packet length
   * Malformed payloads are dropped.
   */

  if (len < 2)
    {
      return;
    }

  header     = (FAR const struct uvc_payload_header_s *)payload;
  header_len = header->bHeaderLength;
  info       = header->bmHeaderInfo;

  if (header_len < 2 || header_len > len)
    {
      return;
    }

  /* Skip payloads marked with the error bit ("error frames"). */

  if (info & UVC_HEADER_ERR)
    {
      return;
    }

  fid      = info & UVC_HEADER_FID;
  data_len = len - header_len;

  UNUSED(fid);

  /* Between frames, skip leading empty payloads.  This camera emits a long
   * burst of zero-data payloads before real video starts; appending them is
   * harmless (0 bytes) but starting a frame on one is not.  Skipping them
   * guarantees a frame always begins on the first real data payload — the
   * frame-start alignment the plain EOF-only path lacked.
   */

  if (priv->frame_offset == 0 && data_len == 0)
    {
      priv->asm_skipped++;
      priv->asm_lastfid = fid;
      return;
    }

  /* DIAG (Step A): dump the raw header sequence of the first 64 non-empty
   * data payloads, to decide whether the tearing lives in the framing layer
   * or the iTD layer.  Reading the real bit pattern of hlen/FID/EOF tells us:
   *   - hlen==12 && EOH stable && FID toggles once per image  => framing layer
   *     (we should switch to FID-primary framing like Linux uvc_video.c)
   *   - hlen garbage / EOH unstable                            => iTD layer
   *     (payload boundaries/lengths are being cut wrong)
   * One-shot (<=64 lines), throttled to non-empty payloads so the startup
   * empty-payload burst does not drown it out.
   */

  if (priv->hdrdump_cnt < 64)
    {
      priv->hdrdump_cnt++;
      syslog(LOG_ERR,
             "HDRSEQ #%u hlen=%u info=%02x dlen=%u fid=%u eof=%u\n",
             priv->hdrdump_cnt, header_len, info, (unsigned)data_len,
             (info & UVC_HEADER_FID) ? 1 : 0,
             (info & UVC_HEADER_EOF) ? 1 : 0);
    }

