input.new_string:
 *   Frame delimiting: FID-primary (ported from Linux uvc_video_decode_start).
 *   HDRSEQ diagnostics proved the earlier "FID flips mid-frame" belief wrong:
 *   on the real data stream hlen is always 12, EOH is always set, and FID
 *   toggles in clean blocks — exactly the pattern Linux assembles full frames
 *   from.  So a FID toggle marks a frame boundary (primary); EOF is a backup
 *   boundary; empty (header-only) payloads still advance FID/EOF bookkeeping
 *   but contribute no data.  This matches how the camera works on Windows and
 *   Linux, which both use this same FID-primary logic.
 *
 ****************************************************************************/

static void usbhost_uvc_process_payload(FAR struct usbhost_uvc_s *priv,
                                        FAR const uint8_t *payload,
                                        size_t len)
{
  FAR const struct uvc_payload_header_s *header;
  uint8_t header_len;
  uint8_t info;
  uint8_t fid;
  size_t  data_len;
  size_t  maxlen;
  size_t  nbytes;

  /* ---- decode_start: sanity checks (Linux uvc_video_decode_start) ----
   *  - packet must be at least 2 bytes
   *  - bHeaderLength must be >= 2 and must not exceed the packet length
   * Malformed payloads are dropped.
   */

  if (len < 2)
    {
      return;
    }

  header     = (FAR const struct uvc_payload_header_s *)payload;
  header_len = header->bHeaderLength;
  info       = header->bmHeaderInfo;

  if (header_len < 2 || header_len > len)
    {
      return;
    }

  /* Skip payloads marked with the error bit ("error frames"). */

  if (info & UVC_HEADER_ERR)
    {
      return;
    }

  fid      = info & UVC_HEADER_FID;
  data_len = len - header_len;

  /* DIAG (Step C): dump the raw header sequence of the first 400 payloads
   * (empty and non-empty), plus the bytes accumulated between FID toggles, to
   * verify a FID block equals one full frame (~154189).  Logs FID/EOF and the
   * running frame_offset at each FID edge.
   */

  if (priv->hdrdump_cnt < 400)
    {
      priv->hdrdump_cnt++;
      syslog(LOG_ERR,
             "HDRSEQ #%u hlen=%u info=%02x dlen=%u fid=%u eof=%u off=%u\n",
             priv->hdrdump_cnt, header_len, info, (unsigned)data_len,
             fid, (info & UVC_HEADER_EOF) ? 1 : 0,
             (unsigned)priv->frame_offset);
    }

  /* ---- FID-primary frame boundary (Linux uvc_video_decode_start) ----
   * A change in the FID bit marks the start of a new frame.  Deliver the
   * frame accumulated so far (if any) before starting the new one.  This is
   * the primary boundary and does not depend on EOF being present.
   *
   * asm_lastfid is initialised to 0xff at stream start, so the first payload
   * never triggers a (spurious) boundary — it just latches the initial FID.
   */

  if (priv->asm_lastfid != 0xff && fid != priv->asm_lastfid)
    {
      if (priv->frame_offset > 0)
        {
          usbhost_uvc_deliver_frame(priv, 2);   /* reason 2 = FID toggle */
        }
    }

  priv->asm_lastfid = fid;

  /* At the very start of a frame, skip leading empty (header-only) payloads
   * so a frame always begins on the first real data payload.  Empty payloads
   * mid-frame are harmless (append 0 bytes) and must not reset anything.
   */

  if (priv->frame_offset == 0 && data_len == 0)
    {
      priv->asm_skipped++;
      return;
    }

  /* ---- decode_data: copy the video data into the assembly buffer ---- */

  maxlen = priv->frame_buflen - priv->frame_offset;
  nbytes = data_len < maxlen ? data_len : maxlen;

  if (nbytes > 0)
    {
      memcpy(priv->frame_buf + priv->frame_offset,
             payload + header_len, nbytes);
      priv->frame_offset += nbytes;
    }

  /* Complete the frame if the buffer overflowed (Linux: "frame complete
   * (overflow)").  Prevents data from spilling into the next frame.
   */

  if (data_len > maxlen)
    {
      usbhost_uvc_deliver_frame(priv, 1);
      return;
    }

  /* ---- decode_end: EOF is the backup frame boundary ---- */

  if (info & UVC_HEADER_EOF)
    {
      if (priv->frame_offset >= 1024)
        {
          usbhost_uvc_deliver_frame(priv, 0);
        }
      else
        {
          priv->frame_offset = 0;   /* drop undersized fragment */
        }
    }
  else if (priv->max_frame_size > 0 &&
           priv->frame_offset >= priv->max_frame_size)
    {
      /* Max-size safety net in case both FID and EOF boundaries are lost. */

      usbhost_uvc_deliver_frame(priv, 1);
    }
}

