/****************************************************************************
 * Name: sunxi_ring_install
 *
 * Description:
 *   Install the iTD ring into the periodic frame list: slot j maps to
 *   itd[j % ISOC_ITD_POOL].  Each iTD's nlp points to the interrupt QH.
 *   The controller visits one iTD per 1ms frame; with N=32 iTDs, each iTD
 *   is revisited every 32ms, giving the consumer a comfortable window to
 *   harvest and re-arm before the controller laps.
 *
 *   Caller must hold g_ehci.lock.
 *
 ****************************************************************************/

static void sunxi_ring_install(void)
{
  int i;
  int slot;
  uint32_t qh_link = g_ring.nlp;

  g_ring.ring_head = 0;
  g_ring.f_head    = 0;
  g_ring.f_tail    = 0;
  g_ring.f_cnt     = 0;

  for (i = 0; i < ISOC_ITD_POOL; i++)
    {
      FAR uint8_t *buffer = g_ring.buf + (size_t)i * ISOC_ITD_BUFSZ;
      sunxi_itd_arm(i, buffer, qh_link);
    }

  for (slot = 0; slot < FRAME_LIST_SIZE; slot++)
    {
      int idx = slot % ISOC_ITD_POOL;
      g_framelist[slot] =
        sunxi_swap32(sunxi_physramaddr((uintptr_t)&g_itdpool[idx].hw)) |
        PFL_TYP_ITD;
    }

  up_clean_dcache((uintptr_t)&g_framelist[0],
                  (uintptr_t)&g_framelist[0] +
                  FRAME_LIST_SIZE * sizeof(uint32_t));
  UP_DSB();
}

