/****************************************************************************
 * Name: sunxi_frame_now
 *
 * Description:
 *   Read the controller's current frame index (1ms granularity).
 *   FRINDEX bits [13:3] = frame number mod periodic_size.
 *
 ****************************************************************************/

static inline uint16_t sunxi_frame_now(void)
{
  return (uint16_t)((sunxi_getreg(&HCOR->frindex) >> 3) & FRAME_LIST_MASK);
}

/****************************************************************************
 * Name: sunxi_ring_install
 *
 * Description:
 *   Install the iTD ring into the periodic frame list using a rolling-window
 *   approach.  Each of the POOL iTDs occupies exactly ONE frame-list slot at
 *   any time.  The POOL slots form a contiguous window starting just ahead
 *   of the current FRINDEX.  All other slots hold the interrupt-QH link.
 *   This eliminates the overwrite race of the old slot%POOL modulo mapping
 *   where the controller could revisit an iTD 32 times before the consumer
 *   harvested it.
 *
 *   Caller must hold g_ehci.lock.
 *
 ****************************************************************************/

static void sunxi_ring_install(void)
{
  int i;
  int slot;
  uint32_t qh_link = g_ring.nlp;
  uint16_t lead;

  g_ring.ring_head = 0;
  g_ring.f_head    = 0;
  g_ring.f_tail    = 0;
  g_ring.f_cnt     = 0;
  g_ring.resync_cnt = 0;

  /* Start: fill ALL slots with the interrupt-QH link (safe baseline). */

  for (slot = 0; slot < FRAME_LIST_SIZE; slot++)
    {
      g_framelist[slot] = qh_link;
    }

  /* Arm all iTDs. */

  for (i = 0; i < ISOC_ITD_POOL; i++)
    {
      FAR uint8_t *buffer = g_ring.buf + (size_t)i * ISOC_ITD_BUFSZ;
      sunxi_itd_arm(i, buffer, qh_link);
    }

  /* Place each iTD into exactly one slot, forming a window of POOL slots
   * starting ISOC_LEAD_GUARD frames ahead of the current FRINDEX.
   */

  lead = (sunxi_frame_now() + ISOC_LEAD_GUARD) & FRAME_LIST_MASK;

  for (i = 0; i < ISOC_ITD_POOL; i++)
    {
      slot = (lead + i) & FRAME_LIST_MASK;
      g_framelist[slot] =
        sunxi_swap32(sunxi_physramaddr((uintptr_t)&g_itdpool[i].hw)) |
        PFL_TYP_ITD;
      g_ring.slot_of[i] = (uint16_t)slot;
    }

  g_ring.next_frame = (lead + ISOC_ITD_POOL) & FRAME_LIST_MASK;

  up_clean_dcache((uintptr_t)&g_framelist[0],
                  (uintptr_t)&g_framelist[0] +
                  FRAME_LIST_SIZE * sizeof(uint32_t));
  UP_DSB();

  syslog(LOG_ERR, "ISOC ring: rolling-window installed, lead=%u next=%u\n",
         lead, g_ring.next_frame);
}

