/* Rolling-window: retire old slot, re-arm iTD, re-link
 * at the leading edge of the window.
 */

{
  FAR uint8_t *buffer = g_ring.buf +
                        (size_t)idx * ISOC_ITD_BUFSZ;
  uint16_t old_slot = g_ring.slot_of[idx];
  uint16_t new_slot;
  uint16_t cur;

  /* 1. Retire: restore old slot to interrupt-QH link. */

  g_framelist[old_slot] = g_ring.nlp;
  up_clean_dcache(
    (uintptr_t)&g_framelist[old_slot],
    (uintptr_t)&g_framelist[old_slot] + sizeof(uint32_t));

  /* 2. Re-arm the iTD with fresh buffer. */

  sunxi_itd_arm(idx, buffer, g_ring.nlp);

  /* 3. Resync guard: if consumer fell behind FRINDEX,
   * jump the leading edge ahead to stay in front.
   */

  cur = sunxi_frame_now();
  {
    int16_t dist = (int16_t)(
      (g_ring.next_frame - cur) & FRAME_LIST_MASK);
    if (dist > (int16_t)(FRAME_LIST_SIZE / 2))
      {
        /* next_frame is behind cur (wrapped) */
        g_ring.next_frame =
          (cur + ISOC_LEAD_GUARD) & FRAME_LIST_MASK;
        g_ring.resync_cnt++;
      }
  }

  /* 4. Link iTD into leading-edge slot. */

  new_slot = g_ring.next_frame;
  g_framelist[new_slot] =
    sunxi_swap32(
      sunxi_physramaddr((uintptr_t)&g_itdpool[idx].hw)) |
    PFL_TYP_ITD;
  up_clean_dcache(
    (uintptr_t)&g_framelist[new_slot],
    (uintptr_t)&g_framelist[new_slot] + sizeof(uint32_t));
  UP_DSB();

  g_ring.slot_of[idx] = new_slot;
  g_ring.next_frame =
    (g_ring.next_frame + 1) & FRAME_LIST_MASK;
}

