  /* ---- Frame boundary: JPEG SOI marker (this is an MJPEG stream) ----
   * Neither EOF nor FID delimits JPEG frames reliably on this camera:
   *   - EOF fires several times per JPEG (verified: soi=1 eoi=0 = 54% of EOF
   *     deliveries — a JPEG started but was cut before its FF D9 end marker).
   *   - FID toggles within a JPEG (verified earlier: median 568-byte shreds).
   * The one unambiguous boundary in an MJPEG stream is the JPEG Start-Of-Image
   * marker FF D8.  A real frame runs from one SOI up to (not including) the
   * next SOI.  So: scan each payload's data for FF D8; when a new SOI appears
   * and we already have data buffered, that buffered data is a complete JPEG —
   * deliver it, then start the new frame at the SOI.  EOF/FID are diagnostic
   * only now.
   */

  priv->asm_lastfid = fid;

  /* Skip header-only (empty) payloads entirely — no data to scan or append. */

  if (data_len == 0)
    {
      if (priv->frame_offset == 0)
        {
          priv->asm_skipped++;
        }

      return;
    }

  /* ---- decode_data with SOI-based framing ----
   * Walk the payload data; whenever a JPEG SOI (FF D8) starts a new image,
   * flush the frame accumulated so far and begin a fresh one.  Data between
   * SOIs is appended to the current frame.
   */

  {
    FAR const uint8_t *data = payload + header_len;
    size_t i;

    for (i = 0; i < data_len; i++)
      {
        /* Detect an SOI (FF D8) at this position.  The FF may be the last
         * byte of the previous payload, so also track a pending-FF state.
         */

        bool is_soi = false;

        if (data[i] == 0xd8)
          {
            if (i > 0 && data[i - 1] == 0xff)
              {
                is_soi = true;
              }
            else if (i == 0 && priv->asm_pending_ff)
              {
                is_soi = true;
              }
          }

        if (is_soi)
          {
            /* The FF D8 begins a new JPEG.  Everything buffered up to the FF
             * (exclusive) is the previous complete frame.  Roll back the FF
             * we already appended, deliver, then restart at FF D8.
             */

            if (priv->frame_offset > 0 && priv->frame_offset >= 2)
              {
                /* Drop the trailing FF that belonged to this new SOI. */

                if (priv->frame_buf[priv->frame_offset - 1] == 0xff)
                  {
                    priv->frame_offset--;
                  }

                if (priv->frame_offset >= 1024)
                  {
                    usbhost_uvc_deliver_frame(priv, 0);
                  }
                else
                  {
                    priv->frame_offset = 0;  /* undersized: drop */
                  }
              }

            /* Start the new frame with the FF D8 we just found. */

            if (priv->frame_offset + 2 <= priv->frame_buflen)
              {
                priv->frame_buf[priv->frame_offset++] = 0xff;
                priv->frame_buf[priv->frame_offset++] = 0xd8;
              }

            priv->asm_pending_ff = false;
            continue;
          }

        /* Ordinary byte: append to the current frame. */

        if (priv->frame_offset < priv->frame_buflen)
          {
            priv->frame_buf[priv->frame_offset++] = data[i];
          }
      }

    /* Remember whether this payload ended on an FF (possible split SOI). */

    priv->asm_pending_ff = (data[data_len - 1] == 0xff);
  }

  /* Overflow safety net: if a frame grows past the max buffer without a new
   * SOI, deliver what we have to avoid unbounded growth.
   */

  if (priv->max_frame_size > 0 &&
      priv->frame_offset >= priv->max_frame_size)
    {
      /* Max-size safety net in case both FID and EOF boundaries are lost. */

      usbhost_uvc_deliver_frame(priv, 1);
    }
}

