  /* ---- Frame boundary: EOF only (MJPEG stream) ----
   * This camera's FID toggles within a JPEG frame (verified: shreds to
   * median 568B).  SOI-scanning was tried but introduces false cuts on
   * JPEG-internal FF D8 sequences.  EOF is the most reliable UVC signal
   * for this device.  The FF D9 补全 in deliver_frame handles the camera's
   * habit of omitting the JPEG EOI marker.
   */

  priv->asm_lastfid = fid;

  /* Skip header-only (empty) payloads: between frames they are just noise. */

  if (priv->frame_offset == 0 && data_len == 0)
    {
      priv->asm_skipped++;
      return;
    }

  /* ---- decode_data: append payload data to the assembly buffer ---- */

  if (data_len > 0 && priv->frame_offset + data_len <= priv->frame_buflen)
    {
      memcpy(priv->frame_buf + priv->frame_offset,
             payload + header_len, data_len);
      priv->frame_offset += data_len;
    }
  else if (data_len > 0)
    {
      /* Overflow: deliver what we have and discard the excess. */

      usbhost_uvc_deliver_frame(priv, 1);
      return;
    }

  /* ---- decode_end: EOF marks the end of the frame ---- */

  if (info & UVC_HEADER_EOF)
    {
      if (priv->frame_offset >= 1024)
