      else
        {
          priv->frame_offset = 0;
        }
    }
  else if (priv->max_frame_size > 0 &&
           priv->frame_offset >= priv->max_frame_size)
    {
      usbhost_uvc_deliver_frame(priv, 1);
    }
}

