/* 3. Bidirectional resync: keep next_frame in a sane
 * range relative to FRINDEX.
 *   - If behind cur: jump ahead (consumer fell behind)
 *   - If too far ahead of cur (> POOL): pull back
 *     (prevents the "drift to 1s" stall observed when
 *     next_frame runs away from FRINDEX)
 */

cur = sunxi_frame_now();
{
  uint16_t dist = (g_ring.next_frame - cur) &
                  FRAME_LIST_MASK;
  if (dist > (FRAME_LIST_SIZE / 2))
    {
      /* next_frame is behind cur (wrapped) */
      g_ring.next_frame =
        (cur + ISOC_LEAD_GUARD) & FRAME_LIST_MASK;
      g_ring.resync_cnt++;
    }
  else if (dist > ISOC_ITD_POOL + ISOC_LEAD_GUARD)
    {
      /* next_frame drifted too far ahead — pull back
       * so the controller reaches re-linked iTDs in
       * ~POOL ms, not after a near-full lap.
       */
      g_ring.next_frame =
        (cur + ISOC_ITD_POOL + ISOC_LEAD_GUARD) &
        FRAME_LIST_MASK;
      g_ring.resync_cnt++;
    }
}

