  /* Preview loop — drain-to-latest strategy.
   * After each decode+blit (which is slow), drain all queued frames except
   * the newest one.  This prevents buffer backpressure from stalling the
   * stream_thread's harvest loop, which is the root cause of data corruption
   * (the controller overwrites iTD data when harvest falls behind).
   */

  while (PREVIEW_FRAMES == 0 || frames < PREVIEW_FRAMES)
    {
      uint32_t n = 0;

      /* Drain: keep DQBUFing and immediately requeuing until DQBUF would
       * block (EAGAIN) — we only keep the last one for decode.  On the
       * first iteration or when no frames are queued yet, the first DQBUF
       * blocks normally (no EAGAIN flag — we want to wait for at least one).
       */

      {
        struct v4l2_buffer drainbuf;
        bool got_one = false;

        for (;;)
          {
            memset(&drainbuf, 0, sizeof(drainbuf));
            drainbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
            drainbuf.memory = V4L2_MEMORY_USERPTR;

            ret = ioctl(fd, VIDIOC_DQBUF, (uintptr_t)&drainbuf);
            if (ret < 0)
              {
                if (!got_one)
                  {
                    printf("ERROR: VIDIOC_DQBUF failed: %d\n", errno);
                    goto done;
                  }

                break;  /* EAGAIN or error after at least one — use last */
              }

            /* If we already had a frame, requeue the PREVIOUS one (skip it) */

            if (got_one)
              {
                ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
              }

            memcpy(&buf, &drainbuf, sizeof(buf));
            got_one = true;
          }
      }

      /* buf now holds the latest (newest) frame.  Snapshot + requeue. */

      {
        n = buf.bytesused;
        if (n > sizeof(g_framecopy))
          {
            n = sizeof(g_framecopy);
          }

        memcpy(g_framecopy, (const void *)buf.m.userptr, n);

        ret = ioctl(fd, VIDIOC_QBUF, (uintptr_t)&buf);
        if (ret < 0)
          {
            printf("ERROR: VIDIOC_QBUF failed: %d\n", errno);
            break;
          }
      }

      /* MJPEG: decode JPEG via tjpgd and blit to LCD. */

      if (n > 1024)
        {
          static uint8_t jdwork[4096];  /* tjpgd work buffer */
          JDEC jdec;
          JRESULT res;
          struct mjpeg_iodev_s iodev;

          iodev.data = g_framecopy;
          iodev.len  = n;
          iodev.pos  = 0;

          res = jd_prepare(&jdec, mjpeg_input, jdwork,
