            gettimeofday(&tc, NULL);
            us_decode += (tc.tv_sec - tb.tv_sec) * 1000000 +
                         (tc.tv_usec - tb.tv_usec);

            fb_blit(jdec.width < TEST_WIDTH ? jdec.width : TEST_WIDTH,
                    jdec.height < TEST_HEIGHT ? jdec.height : TEST_HEIGHT);

            {
              struct timeval td;
              gettimeofday(&td, NULL);
              us_blit += (td.tv_sec - tc.tv_sec) * 1000000 +
                         (td.tv_usec - tc.tv_usec);
            }
          }
        }
    }

  frames++;

  gettimeofday(&t_prev, NULL);  /* mark end of this iteration */

  }
}

