/****************************************************************************
 * apps/examples/person_detect/person_detect_main.cc
 *
 * Object detection using USB UVC camera + TFLite-Micro SSD-MobileNet.
 * Captures MJPEG frames, decodes to RGB, runs SSD detection, draws bounding
 * boxes on the preview, and blits to LCD.
 *
 * Model: /data/detect.tflite (SSD-MobileNet-V1 quantized, COCO 90-class)
 *   Input:  300x300x3 UINT8
 *   Output: locations[1][10][4], classes[1][10], scores[1][10], count[1]
 *
 * Usage: adb push detect.tflite /data/detect.tflite
 *        nsh> person_detect
 ****************************************************************************/

#include <nuttx/config.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cstdarg>
#include <cerrno>
#include <fcntl.h>
#include <unistd.h>
#include <syslog.h>
#include <sys/ioctl.h>
#include <sys/time.h>
#include <sys/stat.h>

#include <nuttx/video/video.h>
#include <nuttx/video/v4l2_cap.h>
#include <nuttx/lcd/lcd_dev.h>

#include "tensorflow/lite/micro/micro_interpreter.h"
#include "tensorflow/lite/micro/micro_log.h"
#include "tensorflow/lite/micro/micro_mutable_op_resolver.h"
#include "tensorflow/lite/micro/system_setup.h"
#include "tensorflow/lite/schema/schema_generated.h"

/****************************************************************************
 * Provide MicroPrintf (LTO strips it from the tflite-micro library)
 ****************************************************************************/

void MicroPrintf(const char* format, ...) {
  va_list args;
  va_start(args, format);
  vprintf(format, args);
  va_end(args);
  printf("\n");
}

void VMicroPrintf(const char* format, va_list args) {
  vprintf(format, args);
  printf("\n");
}

/****************************************************************************
 * Definitions
 ****************************************************************************/

#define VIDEO_DEV_PATH    "/dev/video"
#define LCD_DEV_PATH      "/dev/lcd0"
#define MODEL_PATH        "/data/detect.tflite"

#define LCD_W             320
#define LCD_H             240
#define SSD_INPUT_W       300
#define SSD_INPUT_H       300
#define SSD_INPUT_CH      3
#define SSD_MAX_DETECT    10
#define TENSOR_ARENA_SIZE (10 * 1024 * 1024)  /* 10 MB */
#define CAPTURE_BUF_SIZE  (LCD_W * LCD_H * 2)
#define NUM_BUFFERS       4
#define SCORE_THRESHOLD   0.4f
#define PREVIEW_FRAMES    200

/****************************************************************************
 * TJpgDec integration (reuse from uvc_test)
 ****************************************************************************/

extern "C" {
#include "tjpgd.h"
}

struct jpeg_iodev_s {
  const uint8_t *data;
  size_t len;
  size_t pos;
};

static uint8_t g_rgb[LCD_W * LCD_H * 3];  /* decoded RGB888 frame */
static uint16_t g_fb[LCD_W * LCD_H];      /* RGB565 framebuffer */

static size_t jpeg_input_cb(JDEC *jd, uint8_t *buff, size_t nbyte) {
  struct jpeg_iodev_s *io = (struct jpeg_iodev_s *)jd->device;
  size_t avail = io->len - io->pos;
  if (nbyte > avail) nbyte = avail;
  if (buff) memcpy(buff, io->data + io->pos, nbyte);
  io->pos += nbyte;
  return nbyte;
}

static int jpeg_output_cb(JDEC *jd, void *bitmap, JRECT *rect) {
  uint8_t *src = (uint8_t *)bitmap;
  for (unsigned y = rect->top; y <= rect->bottom && y < LCD_H; y++) {
    for (unsigned x = rect->left; x <= rect->right && x < LCD_W; x++) {
      unsigned idx = (y * LCD_W + x) * 3;
      g_rgb[idx + 0] = *src++;  /* R (tjpgd outputs BGR) → actually B */
      g_rgb[idx + 1] = *src++;  /* G */
      g_rgb[idx + 2] = *src++;  /* B → actually R */
    }
    if (rect->right >= LCD_W)
      src += (rect->right - LCD_W + 1) * 3;
  }
  return 1;
}

static bool decode_jpeg(const uint8_t *jpeg, size_t len) {
  static uint8_t jdwork[4096];
  JDEC jdec;
  struct jpeg_iodev_s io = { jpeg, len, 0 };
  JRESULT res = jd_prepare(&jdec, jpeg_input_cb, jdwork, sizeof(jdwork), &io);
  if (res != JDR_OK) return false;
  return (jd_decomp(&jdec, jpeg_output_cb, 0) == JDR_OK);
}

/****************************************************************************
 * Image processing helpers
 ****************************************************************************/

/* Bilinear resize RGB888 from LCD_W×LCD_H to SSD_INPUT_W×SSD_INPUT_H */

static void resize_rgb_to_ssd(const uint8_t *src, uint8_t *dst) {
  for (int dy = 0; dy < SSD_INPUT_H; dy++) {
    int sy = dy * LCD_H / SSD_INPUT_H;
    for (int dx = 0; dx < SSD_INPUT_W; dx++) {
      int sx = dx * LCD_W / SSD_INPUT_W;
      unsigned sidx = (sy * LCD_W + sx) * 3;
      unsigned didx = (dy * SSD_INPUT_W + dx) * 3;
      /* Note: tjpgd outputs B,G,R but SSD expects R,G,B — swap */
      dst[didx + 0] = src[sidx + 2];  /* R */
      dst[didx + 1] = src[sidx + 1];  /* G */
      dst[didx + 2] = src[sidx + 0];  /* B */
    }
  }
}

/* Draw a rectangle on the RGB565 framebuffer */

static void draw_rect(uint16_t *fb, int x1, int y1, int x2, int y2,
                      uint16_t color) {
  /* clamp */
  if (x1 < 0) x1 = 0; if (x2 >= LCD_W) x2 = LCD_W - 1;
  if (y1 < 0) y1 = 0; if (y2 >= LCD_H) y2 = LCD_H - 1;
  /* horizontal lines */
  for (int x = x1; x <= x2; x++) {
    fb[y1 * LCD_W + x] = color;
    fb[y2 * LCD_W + x] = color;
    if (y1 + 1 < LCD_H) fb[(y1+1) * LCD_W + x] = color;
    if (y2 - 1 >= 0)    fb[(y2-1) * LCD_W + x] = color;
  }
  /* vertical lines */
  for (int y = y1; y <= y2; y++) {
    fb[y * LCD_W + x1] = color;
    fb[y * LCD_W + x2] = color;
    if (x1 + 1 < LCD_W) fb[y * LCD_W + x1 + 1] = color;
    if (x2 - 1 >= 0)    fb[y * LCD_W + x2 - 1] = color;
  }
}

/* Convert g_rgb (BGR from tjpgd) to RGB565 framebuffer */

static void rgb_to_fb(void) {
  for (int i = 0; i < LCD_W * LCD_H; i++) {
    uint8_t b = g_rgb[i * 3 + 0];
    uint8_t g = g_rgb[i * 3 + 1];
    uint8_t r = g_rgb[i * 3 + 2];
    g_fb[i] = ((r & 0xf8) << 8) | ((g & 0xfc) << 3) | (b >> 3);
  }
}

/****************************************************************************
 * LCD helpers
 ****************************************************************************/

static int g_lcdfd = -1;

static void lcd_blit(void) {
  struct lcddev_area_s area;
  memset(&area, 0, sizeof(area));
  area.row_start = 0;
  area.row_end = LCD_H - 1;
  area.col_start = 0;
  area.col_end = LCD_W - 1;
  area.stride = LCD_W * 2;
  area.data = (uint8_t *)g_fb;
  ioctl(g_lcdfd, LCDDEVIO_PUTAREA, (uintptr_t)&area);
}

/****************************************************************************
 * COCO labels (subset)
 ****************************************************************************/

static const char *coco_labels[] = {
  "???", "person", "bicycle", "car", "motorcycle", "airplane",
  "bus", "train", "truck", "boat", "traffic light"
};
#define NUM_LABELS 11

/****************************************************************************
 * Main
 ****************************************************************************/

extern "C" int person_detect_main(int argc, char *argv[])
{
  printf("=== Object Detection (SSD-MobileNet + USB Camera + LCD) ===\n");

  /* ---- Load model from file ---- */

  struct stat st;
  if (stat(MODEL_PATH, &st) < 0) {
    printf("ERROR: Model not found: %s\n", MODEL_PATH);
    printf("Please: adb push detect.tflite /data/detect.tflite\n");
    return -1;
  }

  printf("Loading model: %s (%ld bytes)\n", MODEL_PATH, (long)st.st_size);

  uint8_t *model_data = (uint8_t *)malloc(st.st_size);
  if (!model_data) {
    printf("ERROR: malloc %ld bytes failed\n", (long)st.st_size);
    return -1;
  }

  int mfd = open(MODEL_PATH, O_RDONLY);
  if (mfd < 0 || read(mfd, model_data, st.st_size) != st.st_size) {
    printf("ERROR: read model failed\n");
    free(model_data);
    return -1;
  }
  close(mfd);

  /* ---- Initialize TFLite ---- */

  tflite::InitializeTarget();

  const tflite::Model *model = tflite::GetModel(model_data);
  if (model->version() != TFLITE_SCHEMA_VERSION) {
    printf("ERROR: Model schema version mismatch\n");
    free(model_data);
    return -1;
  }

  /* SSD-MobileNet needs many ops */
  static tflite::MicroMutableOpResolver<10> resolver;
  resolver.AddConv2D();
  resolver.AddDepthwiseConv2D();
  resolver.AddReshape();
  resolver.AddConcatenation();
  resolver.AddLogistic();
  resolver.AddAdd();
  resolver.AddDequantize();
  resolver.AddDetectionPostprocess();
  resolver.AddRelu6();
  resolver.AddMul();

  static uint8_t *tensor_arena = (uint8_t *)malloc(TENSOR_ARENA_SIZE);
  if (!tensor_arena) {
    printf("ERROR: malloc tensor arena (%d bytes) failed\n", TENSOR_ARENA_SIZE);
    free(model_data);
    return -1;
  }

  static tflite::MicroInterpreter interpreter(
    model, resolver, tensor_arena, TENSOR_ARENA_SIZE);

  if (interpreter.AllocateTensors() != kTfLiteOk) {
    printf("ERROR: AllocateTensors failed\n");
    free(model_data);
    free(tensor_arena);
    return -1;
  }

  TfLiteTensor *input = interpreter.input(0);
  printf("Model ready. Input: %dx%dx%d type=%d\n",
         input->dims->data[1], input->dims->data[2],
         input->dims->data[3], input->type);

  /* ---- Initialize LCD ---- */

  g_lcdfd = open(LCD_DEV_PATH, O_RDWR);
  if (g_lcdfd < 0) {
    printf("ERROR: open LCD failed\n");
    free(model_data); free(tensor_arena);
    return -1;
  }

  /* ---- Initialize camera ---- */

  int ret = capture_initialize(VIDEO_DEV_PATH);
  if (ret < 0) {
    printf("ERROR: capture_initialize failed\n");
    close(g_lcdfd); free(model_data); free(tensor_arena);
    return -1;
  }

  int vfd = open(VIDEO_DEV_PATH, O_RDWR);
  if (vfd < 0) {
    printf("ERROR: open video failed\n");
    close(g_lcdfd); free(model_data); free(tensor_arena);
    return -1;
  }

  struct v4l2_format fmt;
  memset(&fmt, 0, sizeof(fmt));
  fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  fmt.fmt.pix.width = LCD_W;
  fmt.fmt.pix.height = LCD_H;
  fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_JPEG;
  ioctl(vfd, VIDIOC_S_FMT, (uintptr_t)&fmt);

  struct v4l2_requestbuffers req;
  memset(&req, 0, sizeof(req));
  req.count = NUM_BUFFERS;
  req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  req.memory = V4L2_MEMORY_USERPTR;
  ioctl(vfd, VIDIOC_REQBUFS, (uintptr_t)&req);

  static uint8_t capbufs[NUM_BUFFERS][CAPTURE_BUF_SIZE];
  struct v4l2_buffer buf;

  for (int i = 0; i < NUM_BUFFERS; i++) {
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_USERPTR;
    buf.index = i;
    buf.m.userptr = (uintptr_t)capbufs[i];
    buf.length = CAPTURE_BUF_SIZE;
    ioctl(vfd, VIDIOC_QBUF, (uintptr_t)&buf);
  }

  enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
  ioctl(vfd, VIDIOC_STREAMON, (uintptr_t)&type);

  printf("Streaming started. Running detection...\n");

  /* ---- SSD input buffer ---- */

  static uint8_t ssd_input[SSD_INPUT_W * SSD_INPUT_H * SSD_INPUT_CH];

  /* ---- Main loop ---- */

  for (int frame = 0; frame < PREVIEW_FRAMES; frame++) {
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_USERPTR;

    ret = ioctl(vfd, VIDIOC_DQBUF, (uintptr_t)&buf);
    if (ret < 0) break;

    /* 1. Decode JPEG → g_rgb (BGR 320x240) */

    bool ok = decode_jpeg((const uint8_t *)buf.m.userptr, buf.bytesused);
    ioctl(vfd, VIDIOC_QBUF, (uintptr_t)&buf);
    if (!ok) continue;

    /* 2. Resize to SSD input (300x300 RGB) */

    resize_rgb_to_ssd(g_rgb, ssd_input);

    /* 3. Copy to model input tensor */

    memcpy(input->data.uint8, ssd_input, SSD_INPUT_W * SSD_INPUT_H * SSD_INPUT_CH);

    /* 4. Run inference */

    struct timeval t0, t1;
    gettimeofday(&t0, NULL);
    TfLiteStatus status = interpreter.Invoke();
    gettimeofday(&t1, NULL);
    uint32_t ms = (t1.tv_sec - t0.tv_sec) * 1000 + (t1.tv_usec - t0.tv_usec) / 1000;

    if (status != kTfLiteOk) {
      printf("[%d] Invoke failed\n", frame);
      continue;
    }

    /* 5. Parse outputs */

    float *locations = interpreter.output(0)->data.f;  /* [1][10][4] */
    float *classes   = interpreter.output(1)->data.f;  /* [1][10] */
    float *scores    = interpreter.output(2)->data.f;  /* [1][10] */
    float *count_f   = interpreter.output(3)->data.f;  /* [1] */
    int det_count = (int)count_f[0];
    if (det_count > SSD_MAX_DETECT) det_count = SSD_MAX_DETECT;

    /* 6. Convert g_rgb to RGB565 framebuffer */

    rgb_to_fb();

    /* 7. Draw bounding boxes on g_fb */

    int persons = 0;
    for (int d = 0; d < det_count; d++) {
      if (scores[d] < SCORE_THRESHOLD) continue;
      int cls = (int)classes[d];

      /* bbox: [y1, x1, y2, x2] normalized 0~1 */
      int y1 = (int)(locations[d * 4 + 0] * LCD_H);
      int x1 = (int)(locations[d * 4 + 1] * LCD_W);
      int y2 = (int)(locations[d * 4 + 2] * LCD_H);
      int x2 = (int)(locations[d * 4 + 3] * LCD_W);

      /* Green for person, yellow for others */
      uint16_t color = (cls == 1) ? 0x07E0 : 0xFFE0;
      draw_rect(g_fb, x1, y1, x2, y2, color);

      if (cls == 1) persons++;

      const char *label = (cls < NUM_LABELS) ? coco_labels[cls] : "obj";
      printf("[%d] %s (%.0f%%) [%d,%d,%d,%d] %ums\n",
             frame, label, scores[d] * 100, x1, y1, x2, y2, ms);
    }

    if (det_count == 0 || persons == 0) {
      if (frame % 10 == 0)
        printf("[%d] no detection %ums\n", frame, ms);
    }

    /* 8. Blit to LCD */

    lcd_blit();
  }

  /* Cleanup */

  ioctl(vfd, VIDIOC_STREAMOFF, (uintptr_t)&type);
  close(vfd);
  capture_uninitialize(VIDEO_DEV_PATH);
  close(g_lcdfd);
  free(model_data);
  free(tensor_arena);

  printf("Done.\n");
  return 0;
}

